// main.cpp
#include <iostream>  // Подключаем заголовочный файл для ввода/вывода

int main() {         // Точка входа в программу — отсюда начинается выполнение
    std::cout << "Hello, C++20!\n";  // Выводим текст в консоль
    return 0;        // Сообщаем операционной системе, что программа завершилась успешно

// Однострочный комментарий — относится до конца строки

/*
  Многострочный комментарий
  Может занимать несколько строк
  Удобен для больших пояснений
*/

/// Doxygen-стиль для автоматической документации
/// @param x входной параметр функции
/// @return результат: x умноженное на 2
int double_it(int x) { return x * 2; }

// Синтаксическая ошибка: забыта точка с запятой
std::cout << "Hello"  // компилятор выдаст: error: expected ';'

// Семантическая ошибка: переменная x не объявлена
std::cout << x;  // компилятор выдаст: error: 'x' was not declared

// Ошибка во время выполнения (UB — неопределённое поведение)
int* p = nullptr;
*p = 42;  // Программа может аварийно завершиться (segfault)
